record.field:
if record.x_rental_date_start and record.x_rental_date_stop and record.product_template_id:
    start = record.x_rental_date_start.date()
    stop = record.x_rental_date_stop.date()
    period_dow = [item.weekday()+1 for item in dateutil.rrule.rrule(freq=dateutil.rrule.DAILY, dtstart=start, until=stop)]

    result = []
    rental_prices = record.product_template_id.x_product_rental_price_ids.sorted(lambda p: len(p.x_rental_day_ids), reverse=True)
    dow_to_process = period_dow[:] # copy
    while dow_to_process:
        found = False
        for rental_price in rental_prices:
            rental_price_dow = sorted([d.x_dayofweek for d in rental_price.x_rental_day_ids])
            if dow_to_process[:len(rental_price_dow)] == rental_price_dow and len(rental_price_dow) <= len(dow_to_process):
                result.append(rental_price)
                found = True
                dow_to_process = dow_to_process[len(rental_price_dow):]
                break;
        if not found:
            dow_to_process = dow_to_process[1:] # remove first element

    record.write({
        "price_unit": sum([item.x_price for item in result]),
        "name": record._get_sale_order_line_multiline_description_sale() + f"\nFrom {start.isoformat()} to {stop.isoformat()}"
    })
